// Parse a simple YAML document into our YamlValue structure
fn simple_yaml_parse(yaml: &str) -> Result<HashMap<String, YamlValue>, String> {
    // Use a simple state-machine parser for our specific YAML format
    let mut result: HashMap<String, YamlValue> = HashMap::new();
    let lines: Vec<&str> = yaml.lines().collect();

    let mut i = 0;
    // Skip document start markers
    while i < lines.len() && (lines[i].trim().is_empty() || lines[i].trim() == "---") {
        i += 1;
    }

    // Parse top-level keys
    while i < lines.len() {
        let line = lines[i];
        if line.trim().is_empty() || line.trim().starts_with('#') {
            i += 1;
            continue;
        }

        let indent = get_indent(line);
        if indent == 0 {
            if let Some((key, rest)) = parse_key_value(line) {
                if rest.is_empty() || rest == "{}" {
                    // It's a map, parse sub-keys
                    if rest == "{}" {
                        result.insert(key, YamlValue::Map(HashMap::new()));
                        i += 1;
                    } else {
                        i += 1;
                        let (submap, new_i) = parse_map(&lines, i, 2)?;
                        result.insert(key, YamlValue::Map(submap));
                        i = new_i;
                    }
                } else {
                    // Simple value
                    result.insert(key, YamlValue::Str(parse_yaml_str_value(rest)));
                    i += 1;
                }
            } else {
                i += 1;
            }
        } else {
            i += 1;
        }
    }

    Ok(result)
}

fn parse_map(lines: &[&str], start: usize, expected_indent: usize) -> Result<(HashMap<String, YamlValue>, usize), String> {
    let mut map: HashMap<String, YamlValue> = HashMap::new();
    let mut i = start;

    while i < lines.len() {
        let line = lines[i];
        if line.trim().is_empty() || line.trim().starts_with('#') {
            i += 1;
            continue;
        }

        let indent = get_indent(line);
        if indent < expected_indent {
            break;
        }
        if indent == expected_indent {
            if let Some((key, rest)) = parse_key_value(line) {
                let rest = rest.trim().to_string();
                if rest.is_empty() || rest == "{}" {
                    if rest == "{}" {
                        map.insert(key, YamlValue::Map(HashMap::new()));
                        i += 1;
                    } else {
                        i += 1;
                        let (submap, new_i) = parse_map(lines, i, expected_indent + 2)?;
                        map.insert(key, YamlValue::Map(submap));
                        i = new_i;
                    }
                } else {
                    map.insert(key, YamlValue::Str(parse_yaml_str_value(&rest)));
                    i += 1;
                }
            } else {
                i += 1;
            }
        } else {
            // Deeper indent - might be continuation or error
            i += 1;
        }
    }

    Ok((map, i))
}

fn get_indent(line: &str) -> usize {
    line.len() - line.trim_start().len()
}

fn parse_key_value(line: &str) -> Option<(String, &str)> {
    let trimmed = line.trim();
    if let Some(colon_pos) = trimmed.find(':') {
        let key = trimmed[..colon_pos].trim().to_string();
        if key.is_empty() { return None; }
        let rest = trimmed[colon_pos + 1..].trim();
        Some((key, rest))
    } else {
        None
    }
}

fn parse_yaml_str_value(s: &str) -> String {
    let s = s.trim();
    // Handle quoted strings
    if (s.starts_with('"') && s.ends_with('"')) || (s.starts_with('\'') && s.ends_with('\'')) {
        s[1..s.len()-1].to_string()
    } else {
        s.to_string()
    }
}
