use crate::theme::Theme;
use crate::css_colors;
use std::collections::HashMap;

// Apply a theme to an i3 config file content
pub fn apply_theme(config: &str, theme: &Theme) -> String {
    let lines: Vec<&str> = config.lines().collect();
    let mut output_lines: Vec<String> = Vec::new();

    let mut i = 0;
    let mut in_bar = false;
    let mut in_bar_colors = false;
    let mut bar_brace_depth = 0;
    let mut colors_brace_depth = 0;

    // Track which color types have been seen
    let mut bar_separator_seen = false;
    let mut bar_background_seen = false;
    let mut bar_statusline_seen = false;
    let mut bar_focused_workspace_seen = false;
    let mut bar_active_workspace_seen = false;
    let mut bar_inactive_workspace_seen = false;
    let mut bar_urgent_workspace_seen = false;

    // For colors block - pending additions
    let mut pending_bar_additions: Vec<String> = Vec::new();

    // Client line tracking
    let mut client_focused_seen = false;
    let mut client_focused_inactive_seen = false;
    let mut client_unfocused_seen = false;
    let mut client_urgent_seen = false;

    while i < lines.len() {
        let line = lines[i];
        let trimmed = line.trim();

        // Check if we're entering a bar block
        // "bar {" or "bar{" where { is on the same line and it's a top-level keyword
        if !in_bar && !in_bar_colors {
            // Check if this is a "bar {" line (with { at end or on same line but not "bar {}")
            if is_bar_start(trimmed) {
                in_bar = true;
                bar_brace_depth = 1;
                in_bar_colors = false;
                bar_separator_seen = false;
                bar_background_seen = false;
                bar_statusline_seen = false;
                bar_focused_workspace_seen = false;
                bar_active_workspace_seen = false;
                bar_inactive_workspace_seen = false;
                bar_urgent_workspace_seen = false;
                output_lines.push(line.to_string());
                i += 1;
                continue;
            }
        }

        if in_bar {
            // Count braces
            let open_count = trimmed.chars().filter(|&c| c == '{').count();
            let close_count = trimmed.chars().filter(|&c| c == '}').count();

            // Check for colors { block
            if !in_bar_colors && is_colors_start(trimmed) {
                in_bar_colors = true;
                colors_brace_depth = 1;
                output_lines.push(line.to_string());
                i += 1;
                continue;
            }

            if in_bar_colors {
                // Inside colors block
                if trimmed == "}" || trimmed == "};" {
                    // End of colors block - add any missing items before closing
                    in_bar_colors = false;

                    // Add missing items
                    let additions = get_bar_color_additions(theme,
                        bar_separator_seen, bar_background_seen, bar_statusline_seen,
                        bar_focused_workspace_seen, bar_active_workspace_seen,
                        bar_inactive_workspace_seen, bar_urgent_workspace_seen);
                    for a in additions {
                        output_lines.push(a);
                    }

                    output_lines.push(line.to_string());
                    i += 1;
                    continue;
                }

                // Process color lines inside colors block
                if let Some(new_line) = process_bar_color_line(line, theme,
                    &mut bar_separator_seen, &mut bar_background_seen,
                    &mut bar_statusline_seen, &mut bar_focused_workspace_seen,
                    &mut bar_active_workspace_seen, &mut bar_inactive_workspace_seen,
                    &mut bar_urgent_workspace_seen) {
                    output_lines.push(new_line);
                } else {
                    output_lines.push(line.to_string());
                }
                i += 1;
                continue;
            }

            // Check if this is the closing } of the bar block
            // We need to add colors block before it if none was seen
            if trimmed == "}" {
                bar_brace_depth -= 1;
                if bar_brace_depth == 0 {
                    in_bar = false;
                    // If we never saw a colors block, add it before the closing }
                    if !bar_background_seen && !bar_separator_seen && !bar_statusline_seen
                        && !bar_focused_workspace_seen {
                        // Add colors block
                        let colors_block = generate_colors_block(theme);
                        for l in colors_block {
                            output_lines.push(l);
                        }
                    }
                    output_lines.push(line.to_string());
                    i += 1;
                    continue;
                }
            } else {
                // Update brace depth for other braces
                if open_count > 0 || close_count > 0 {
                    bar_brace_depth += open_count as i32;
                    bar_brace_depth -= close_count as i32;
                }
            }

            output_lines.push(line.to_string());
            i += 1;
            continue;
        }

        // Check for client.* lines
        if let Some(new_line) = process_client_line(line, theme,
            &mut client_focused_seen, &mut client_focused_inactive_seen,
            &mut client_unfocused_seen, &mut client_urgent_seen) {
            output_lines.push(new_line);
            i += 1;
            continue;
        }

        output_lines.push(line.to_string());
        i += 1;
    }

    // Append missing client.* lines at end
    let client_additions = get_client_additions(theme,
        client_focused_seen, client_focused_inactive_seen,
        client_unfocused_seen, client_urgent_seen);
    for a in client_additions {
        output_lines.push(a);
    }

    let mut result = output_lines.join("\n");
    // Ensure ends with newline
    if !result.ends_with('\n') {
        result.push('\n');
    }
    result
}

fn is_bar_start(trimmed: &str) -> bool {
    // Match "bar {" where the { is at the end of the line (possibly with spaces)
    // but NOT "bar {}" (empty on one line)
    if trimmed == "bar {" || trimmed.starts_with("bar {") {
        // Check it's not "bar {}"
        let after_brace: &str = trimmed.trim_start_matches("bar").trim_start_matches('{').trim();
        // Actually: "bar {" -> after "bar " = "{", not empty after {
        // "bar {}" -> that's just empty bar block
        // We check: starts with "bar" followed by whitespace and "{"
        let rest = trimmed.trim_start_matches("bar").trim_start();
        if rest.starts_with('{') {
            let after = rest.trim_start_matches('{').trim();
            // If after { is empty or only whitespace, this is a valid bar start
            // but NOT if it's immediately closed: "bar {}"
            if after.is_empty() {
                return true;
            }
            // "bar { ... }" is NOT what we match - we look for multi-line bar blocks
        }
    }
    false
}

fn is_colors_start(trimmed: &str) -> bool {
    trimmed == "colors {" || trimmed.starts_with("colors {")
}

// Process a line inside bar.colors and replace values if needed
fn process_bar_color_line(line: &str, theme: &Theme,
    separator_seen: &mut bool, background_seen: &mut bool,
    statusline_seen: &mut bool, focused_ws_seen: &mut bool,
    active_ws_seen: &mut bool, inactive_ws_seen: &mut bool,
    urgent_ws_seen: &mut bool) -> Option<String> {

    let trimmed = line.trim();
    let indent = get_line_indent(line);

    // Single-value lines
    if let Some(new_val) = match_and_replace_single(trimmed, "separator", theme.bar_separator.as_deref(), 
            theme.bar_separator.as_deref().and_then(|n| theme.resolve(n))) {
        *separator_seen = true;
        return Some(format!("{}{}", indent, new_val));
    }
    if let Some(new_val) = match_and_replace_single(trimmed, "background", theme.bar_background.as_deref(),
            theme.bar_background.as_deref().and_then(|n| theme.resolve(n))) {
        *background_seen = true;
        return Some(format!("{}{}", indent, new_val));
    }
    if let Some(new_val) = match_and_replace_single(trimmed, "statusline", theme.bar_statusline.as_deref(),
            theme.bar_statusline.as_deref().and_then(|n| theme.resolve(n))) {
        *statusline_seen = true;
        return Some(format!("{}{}", indent, new_val));
    }

    // Workspace lines (3 or 4 color values)
    if starts_with_keyword(trimmed, "focused_workspace") {
        *focused_ws_seen = true;
        if let Some(ref bwc) = theme.bar_focused_workspace {
            let (b, bg, t) = theme.resolve_bwc(bwc);
            if let (Some(border), Some(bg_val), Some(text)) = (b, bg, t) {
                let orig_3rd = extract_nth_color(trimmed, 3);
                return Some(format!("{}focused_workspace {} {} {} {}",
                    indent, border, bg_val, text,
                    orig_3rd.map(|c| format!("{}", c)).unwrap_or_default()));
            }
        }
        return None;
    }
    if starts_with_keyword(trimmed, "active_workspace") {
        *active_ws_seen = true;
        if let Some(ref bwc) = theme.bar_active_workspace {
            let (b, bg, t) = theme.resolve_bwc(bwc);
            if let (Some(border), Some(bg_val), Some(text)) = (b, bg, t) {
                let orig_3rd = extract_nth_color(trimmed, 3);
                return Some(format!("{}active_workspace {} {} {} {}",
                    indent, border, bg_val, text,
                    orig_3rd.map(|c| format!("{}", c)).unwrap_or_default()));
            }
        }
        return None;
    }
    if starts_with_keyword(trimmed, "inactive_workspace") {
        *inactive_ws_seen = true;
        if let Some(ref bwc) = theme.bar_inactive_workspace {
            let (b, bg, t) = theme.resolve_bwc(bwc);
            if let (Some(border), Some(bg_val), Some(text)) = (b, bg, t) {
                let orig_3rd = extract_nth_color(trimmed, 3);
                return Some(format!("{}inactive_workspace {} {} {} {}",
                    indent, border, bg_val, text,
                    orig_3rd.map(|c| format!("{}", c)).unwrap_or_default()));
            }
        }
        return None;
    }
    if starts_with_keyword(trimmed, "urgent_workspace") {
        *urgent_ws_seen = true;
        if let Some(ref bwc) = theme.bar_urgent_workspace {
            let (b, bg, t) = theme.resolve_bwc(bwc);
            if let (Some(border), Some(bg_val), Some(text)) = (b, bg, t) {
                let orig_3rd = extract_nth_color(trimmed, 3);
                return Some(format!("{}urgent_workspace {} {} {} {}",
                    indent, border, bg_val, text,
                    orig_3rd.map(|c| format!("{}", c)).unwrap_or_default()));
            }
        }
        return None;
    }

    None
}

fn starts_with_keyword(s: &str, keyword: &str) -> bool {
    if let Some(rest) = s.strip_prefix(keyword) {
        rest.is_empty() || rest.starts_with(' ') || rest.starts_with('\t')
    } else {
        false
    }
}

fn match_and_replace_single(trimmed: &str, keyword: &str, _name: Option<&str>, value: Option<&str>) -> Option<String> {
    if value.is_none() { return None; }
    let val = value.unwrap();

    if starts_with_keyword(trimmed, keyword) {
        // Replace the hex value
        Some(format!("{} {}", keyword, val))
    } else {
        None
    }
}

fn extract_nth_color(line: &str, n: usize) -> Option<&str> {
    // Extract the nth hex color (1-indexed) from a line like "keyword #HEX1 #HEX2 #HEX3"
    let mut count = 0;
    let mut pos = 0;
    let bytes = line.as_bytes();

    while pos < bytes.len() {
        if bytes[pos] == b'#' {
            count += 1;
            let start = pos;
            pos += 1;
            while pos < bytes.len() && (bytes[pos].is_ascii_hexdigit()) {
                pos += 1;
            }
            if count == n {
                return Some(&line[start..pos]);
            }
        } else {
            pos += 1;
        }
    }
    None
}

fn get_line_indent(line: &str) -> &str {
    let trimmed = line.trim_start();
    &line[..line.len() - trimmed.len()]
}

