            pos += 1;
            while pos < bytes.len() && bytes[pos].is_ascii_hexdigit() {
                pos += 1;
            }
            if pos - start > 1 {
                out.push(line[start..pos].to_uppercase());
            }
        } else {
            pos += 1;
        }
    }
}

