fn parse_config_colors(config: &str) -> (Vec<String>, Vec<String>) {
    let mut bar_colors: Vec<String> = Vec::new();
    let mut window_colors: Vec<String> = Vec::new();

    let mut in_bar = false;
    let mut in_bar_colors = false;

    for line in config.lines() {
        let trimmed = line.trim();

        if is_bar_start(trimmed) {
            in_bar = true;
            in_bar_colors = false;
            continue;
        }

        if in_bar {
            if is_colors_start(trimmed) {
                in_bar_colors = true;
                continue;
            }

            if in_bar_colors {
                if trimmed == "}" {
                    in_bar_colors = false;
                    // Also check if this closes bar
                    continue;
                }
                // Collect hex values from this line
                extract_hex_values(trimmed, &mut bar_colors);
                continue;
            }

            if trimmed == "}" {
                in_bar = false;
                continue;
            }
        }

        // Client lines
        if trimmed.starts_with("client.") {
            extract_hex_values(trimmed, &mut window_colors);
        }
    }

    (bar_colors, window_colors)
}

fn extract_hex_values(line: &str, out: &mut Vec<String>) {
    let mut pos = 0;
    let bytes = line.as_bytes();
    while pos < bytes.len() {
        if bytes[pos] == b'#' {
            let start = pos;
            pos += 1;
            while pos < bytes.len() && bytes[pos].is_ascii_hexdigit() {
                pos += 1;
            }
            if pos - start > 1 {
                out.push(line[start..pos].to_uppercase());
            }
        } else {
            pos += 1;
        }
    }
}

