fn process_client_line(line: &str, theme: &Theme,
    focused_seen: &mut bool, focused_inactive_seen: &mut bool,
    unfocused_seen: &mut bool, urgent_seen: &mut bool) -> Option<String> {

    let trimmed = line.trim();

    if starts_with_keyword(trimmed, "client.focused") && !starts_with_keyword(trimmed, "client.focused_inactive") {
        *focused_seen = true;
        if let Some(ref wcs) = theme.window_focused {
            let (b, bg, t, ind) = theme.resolve_wcs(wcs);
            if let (Some(border), Some(bg_val), Some(text), Some(indicator)) = (b, bg, t, ind) {
                return Some(format!("client.focused {} {} {} {}", border, bg_val, text, indicator));
            }
        }
        return None;
    }
    if starts_with_keyword(trimmed, "client.focused_inactive") {
