// Convert a config file to a theme YAML (--to-theme)
pub fn config_to_theme(config: &str) -> String {
    let mut all_colors: Vec<(String, String)> = Vec::new(); // (position_key, hex_value)
    let mut seen_hexes: Vec<String> = Vec::new();

    // Parse the config to find all color values, in order
    let (bar_data, window_data) = parse_config_colors(config);

    // Collect all unique hex colors in order of first appearance
    let mut hex_order: Vec<String> = Vec::new();
    let mut seen_set: std::collections::HashSet<String> = std::collections::HashSet::new();

    // Bar colors order: background, statusline, separator, workspace types
    for hex in bar_data.iter().chain(window_data.iter()) {
        let upper_hex = normalize_hex(hex);
        if !seen_set.contains(&upper_hex) {
            seen_set.insert(upper_hex.clone());
            hex_order.push(upper_hex);
        }
    }

    // Map hex values to CSS color names
    let mut hex_to_name: HashMap<String, String> = HashMap::new();
    let mut name_count: HashMap<String, usize> = HashMap::new();

    for hex in &hex_order {
        let base_name = css_colors::find_nearest_color(hex);
        let count = name_count.entry(base_name.to_string()).or_insert(0);
        let name = if *count == 0 {
            base_name.to_string()
        } else {
            format!("{}-{}", base_name, count)
        };
        *count += 1;
        hex_to_name.insert(hex.clone(), name);
    }

    // Generate theme YAML
    generate_theme_yaml(&bar_data, &window_data, &hex_to_name, &hex_order)
}

fn normalize_hex(hex: &str) -> String {
    hex.to_uppercase()
}

