// Returns true if this line opens a bar block in a way we can process
fn is_bar_open(trimmed: &str) -> bool {
    // Match "bar {" where { is not immediately closed on same line
    // Specifically: "bar" followed by optional whitespace then "{" then end of line
    // NOT "bar {}" 
    if !trimmed.starts_with("bar") {
        return false;
    }
    let rest = trimmed[3..].trim_start();
    if rest.starts_with('{') {
        let after = rest[1..].trim();
        // "bar {" with nothing after { -> valid bar open
        // "bar { something }" -> NOT what we handle
        return after.is_empty();
    }
    false
}

fn process_bar_block(lines: &[&str], start: usize, theme: &Theme) -> (Vec<String>, usize) {
    let mut result: Vec<String> = Vec::new();
    let mut i = start;
    let mut depth = 1i32; // we're inside bar {
    let mut colors_block_seen = false;

    // Track what we've seen in the colors block
    let mut sep_seen = false;
    let mut bg_seen = false;
    let mut sl_seen = false;
    let mut fw_seen = false;
    let mut aw_seen = false;
    let mut iw_seen = false;
    let mut uw_seen = false;

    while i < lines.len() {
        let line = lines[i];
        let trimmed = line.trim();

        // Check for colors { block
        if depth == 1 && !colors_block_seen && is_colors_open(trimmed) {
            colors_block_seen = true;
            result.push(line.to_string());
            i += 1;

            // Process colors block
            while i < lines.len() {
                let cline = lines[i];
                let ctrimmed = cline.trim();

                if ctrimmed == "}" || ctrimmed == "};" {
                    // End of colors block - add missing entries
                    let additions = get_bar_color_additions(theme,
                        sep_seen, bg_seen, sl_seen,
                        fw_seen, aw_seen, iw_seen, uw_seen);
                    for a in additions {
                        result.push(a);
                    }
                    result.push(cline.to_string());
                    i += 1;
                    break;
                }

                // Try to replace color lines
                let new_line = replace_bar_color_line(cline, theme,
                    &mut sep_seen, &mut bg_seen, &mut sl_seen,
                    &mut fw_seen, &mut aw_seen, &mut iw_seen, &mut uw_seen);
                result.push(new_line);
                i += 1;
            }
            continue;
        }

        // Check for closing } of bar block
        if trimmed == "}" {
            depth -= 1;
            if depth == 0 {
                // If we never saw a colors block, add one now
                if !colors_block_seen {
                    let colors_block = generate_colors_block(theme);
                    for l in colors_block {
                        result.push(l);
                    }
                }
                result.push(line.to_string());
                i += 1;
                break;
            }
        } else {
            // Count depth changes
            for ch in trimmed.chars() {
                match ch {
                    '{' => depth += 1,
                    '}' => depth -= 1,
                    _ => {}
                }
            }
        }

        result.push(line.to_string());
        i += 1;
    }

    (result, i)
}

fn is_colors_open(trimmed: &str) -> bool {
    if !trimmed.starts_with("colors") {
        return false;
    }
    let rest = trimmed[6..].trim_start();
    if rest.starts_with('{') {
        let after = rest[1..].trim();
        return after.is_empty();
    }
    false
}

fn replace_bar_color_line(line: &str, theme: &Theme,
    sep_seen: &mut bool, bg_seen: &mut bool, sl_seen: &mut bool,
    fw_seen: &mut bool, aw_seen: &mut bool, iw_seen: &mut bool,
    uw_seen: &mut bool) -> String {

    let trimmed = line.trim();
    let indent = get_indent(line);

    // Check single-value lines
    if starts_with_kw(trimmed, "separator") {
        *sep_seen = true;
        if let Some(val) = resolve_bar_color(&theme.bar_separator, theme) {
            return format!("{}separator {}", indent, val);
        }
        return line.to_string();
    }
    if starts_with_kw(trimmed, "background") {
        *bg_seen = true;
        if let Some(val) = resolve_bar_color(&theme.bar_background, theme) {
            return format!("{}background {}", indent, val);
        }
        return line.to_string();
    }
    if starts_with_kw(trimmed, "statusline") {
        *sl_seen = true;
        if let Some(val) = resolve_bar_color(&theme.bar_statusline, theme) {
            return format!("{}statusline {}", indent, val);
        }
        return line.to_string();
    }

    // Workspace lines
    if starts_with_kw(trimmed, "focused_workspace") {
        *fw_seen = true;
        if let Some(ref bwc) = theme.bar_focused_workspace {
            if let Some(new_line) = replace_workspace_line(trimmed, theme, bwc, indent) {
                return new_line;
            }
        }
        return line.to_string();
    }
    if starts_with_kw(trimmed, "active_workspace") {
        *aw_seen = true;
        if let Some(ref bwc) = theme.bar_active_workspace {
            if let Some(new_line) = replace_workspace_line(trimmed, theme, bwc, indent) {
                return new_line;
            }
        }
        return line.to_string();
    }
    if starts_with_kw(trimmed, "inactive_workspace") {
        *iw_seen = true;
        if let Some(ref bwc) = theme.bar_inactive_workspace {
            if let Some(new_line) = replace_workspace_line(trimmed, theme, bwc, indent) {
                return new_line;
            }
        }
        return line.to_string();
    }
    if starts_with_kw(trimmed, "urgent_workspace") {
        *uw_seen = true;
        if let Some(ref bwc) = theme.bar_urgent_workspace {
            if let Some(new_line) = replace_workspace_line(trimmed, theme, bwc, indent) {
                return new_line;
            }
        }
        return line.to_string();
    }

    line.to_string()
}

fn replace_workspace_line(trimmed: &str, theme: &Theme, 
    bwc: &crate::theme::BarWorkspaceColors, indent: &str) -> Option<String> {
    let (b, bg, t) = theme.resolve_bwc(bwc);
    let (border, bg_val, text) = (b?, bg?, t?);

    // Get keyword
    let kw = trimmed.split_whitespace().next()?;

    // Get original 3rd color as the 4th value
    let orig_3rd = extract_nth_color(trimmed, 3);

    let fourth = orig_3rd.map(|c| format!(" {}", c)).unwrap_or_default();
    Some(format!("{}{} {} {} {}{}", indent, kw, border, bg_val, text, fourth))
}

fn extract_nth_color(s: &str, n: usize) -> Option<&str> {
    let mut count = 0;
    let bytes = s.as_bytes();
    let mut pos = 0;

    while pos < bytes.len() {
        if bytes[pos] == b'#' {
            count += 1;
            let start = pos;
            pos += 1;
            while pos < bytes.len() && bytes[pos].is_ascii_hexdigit() {
                pos += 1;
            }
            if count == n {
                return Some(&s[start..pos]);
            }
        } else {
            pos += 1;
        }
    }
    None
}

fn resolve_bar_color(name: &Option<String>, theme: &Theme) -> Option<&str> {
    name.as_ref().and_then(|n| theme.resolve(n))
}

fn get_bar_color_additions(theme: &Theme,
    sep: bool, bg: bool, sl: bool,
    fw: bool, aw: bool, iw: bool, uw: bool) -> Vec<String> {

    let mut additions = Vec::new();

    if !sep {
        if let Some(val) = resolve_bar_color(&theme.bar_separator, theme) {
            additions.push(format!("    separator {}", val));
        }
    }
    if !bg {
        if let Some(val) = resolve_bar_color(&theme.bar_background, theme) {
            additions.push(format!("    background {}", val));
        }
    }
    if !sl {
        if let Some(val) = resolve_bar_color(&theme.bar_statusline, theme) {
            additions.push(format!("    statusline {}", val));
        }
    }

    macro_rules! add_workspace {
        ($seen:expr, $field:expr, $name:expr) => {
            if !$seen {
                if let Some(ref bwc) = $field {
                    let (b, bg2, t) = theme.resolve_bwc(bwc);
                    if let (Some(border), Some(bg_val), Some(text)) = (b, bg2, t) {
                        additions.push(format!("    {} {} {} {} ", $name, border, bg_val, text));
                    }
                }
            }
        }
    }

    add_workspace!(fw, theme.bar_focused_workspace, "focused_workspace");
    add_workspace!(aw, theme.bar_active_workspace, "active_workspace");
    add_workspace!(iw, theme.bar_inactive_workspace, "inactive_workspace");
    add_workspace!(uw, theme.bar_urgent_workspace, "urgent_workspace");

    additions
}

fn generate_colors_block(theme: &Theme) -> Vec<String> {
    let mut lines = Vec::new();
    lines.push("  colors {".to_string());

    if let Some(ref name) = theme.bar_separator {
        if let Some(val) = theme.resolve(name) {
            lines.push(format!("    separator {}", val));
        }
    }
    if let Some(ref name) = theme.bar_background {
        if let Some(val) = theme.resolve(name) {
            lines.push(format!("    background {}", val));
        }
    }
    if let Some(ref name) = theme.bar_statusline {
        if let Some(val) = theme.resolve(name) {
            lines.push(format!("    statusline {}", val));
        }
    }

    macro_rules! add_ws {
        ($field:expr, $name:expr) => {
            if let Some(ref bwc) = $field {
                let (b, bg, t) = theme.resolve_bwc(bwc);
                if let (Some(border), Some(bg_val), Some(text)) = (b, bg, t) {
                    lines.push(format!("    {} {} {} {} ", $name, border, bg_val, text));
                }
            }
        }
    }

    add_ws!(theme.bar_focused_workspace, "focused_workspace");
    add_ws!(theme.bar_active_workspace, "active_workspace");
    add_ws!(theme.bar_inactive_workspace, "inactive_workspace");
    add_ws!(theme.bar_urgent_workspace, "urgent_workspace");

    lines.push("  }".to_string());
    lines
}

fn replace_client_line(line: &str, theme: &Theme,
    focused_seen: &mut bool,
    focused_inactive_seen: &mut bool,
    unfocused_seen: &mut bool,
    urgent_seen: &mut bool) -> Option<String> {

    let trimmed = line.trim();

    // Order matters: check focused_inactive before focused
    if starts_with_kw(trimmed, "client.focused_inactive") {
        *focused_inactive_seen = true;
        if let Some(ref wcs) = theme.window_focused_inactive {
            let (b, bg, t, ind) = theme.resolve_wcs(wcs);
            if let (Some(border), Some(bg_val), Some(text), Some(indicator)) = (b, bg, t, ind) {
                return Some(format!("client.focused_inactive {} {} {} {}", border, bg_val, text, indicator));
            }
        }
        return Some(line.to_string());
    }
    if starts_with_kw(trimmed, "client.focused") {
        *focused_seen = true;
        if let Some(ref wcs) = theme.window_focused {
            let (b, bg, t, ind) = theme.resolve_wcs(wcs);
            if let (Some(border), Some(bg_val), Some(text), Some(indicator)) = (b, bg, t, ind) {
                return Some(format!("client.focused {} {} {} {}", border, bg_val, text, indicator));
            }
        }
        return Some(line.to_string());
    }
    if starts_with_kw(trimmed, "client.unfocused") {
        *unfocused_seen = true;
        if let Some(ref wcs) = theme.window_unfocused {
            let (b, bg, t, ind) = theme.resolve_wcs(wcs);
            if let (Some(border), Some(bg_val), Some(text), Some(indicator)) = (b, bg, t, ind) {
                return Some(format!("client.unfocused {} {} {} {}", border, bg_val, text, indicator));
            }
        }
        return Some(line.to_string());
    }
    if starts_with_kw(trimmed, "client.urgent") {
        *urgent_seen = true;
        if let Some(ref wcs) = theme.window_urgent {
            let (b, bg, t, ind) = theme.resolve_wcs(wcs);
            if let (Some(border), Some(bg_val), Some(text), Some(indicator)) = (b, bg, t, ind) {
                return Some(format!("client.urgent {} {} {} {}", border, bg_val, text, indicator));
            }
        }
        return Some(line.to_string());
    }

    None
}

fn append_missing_clients(result: &mut Vec<String>, theme: &Theme,
    focused: bool, focused_inactive: bool,
    unfocused: bool, urgent: bool) {

    if !focused {
        if let Some(ref wcs) = theme.window_focused {
            let (b, bg, t, ind) = theme.resolve_wcs(wcs);
            if let (Some(border), Some(bg_val), Some(text), Some(indicator)) = (b, bg, t, ind) {
                result.push(format!("client.focused {} {} {} {}", border, bg_val, text, indicator));
            }
        }
    }
    if !focused_inactive {
        if let Some(ref wcs) = theme.window_focused_inactive {
            let (b, bg, t, ind) = theme.resolve_wcs(wcs);
            if let (Some(border), Some(bg_val), Some(text), Some(indicator)) = (b, bg, t, ind) {
                result.push(format!("client.focused_inactive {} {} {} {}", border, bg_val, text, indicator));
            }
        }
    }
    if !unfocused {
        if let Some(ref wcs) = theme.window_unfocused {
            let (b, bg, t, ind) = theme.resolve_wcs(wcs);
            if let (Some(border), Some(bg_val), Some(text), Some(indicator)) = (b, bg, t, ind) {
                result.push(format!("client.unfocused {} {} {} {}", border, bg_val, text, indicator));
            }
        }
    }
    if !urgent {
        if let Some(ref wcs) = theme.window_urgent {
            let (b, bg, t, ind) = theme.resolve_wcs(wcs);
            if let (Some(border), Some(bg_val), Some(text), Some(indicator)) = (b, bg, t, ind) {
                result.push(format!("client.urgent {} {} {} {}", border, bg_val, text, indicator));
            }
        }
    }
}

fn starts_with_kw(s: &str, kw: &str) -> bool {
    if let Some(rest) = s.strip_prefix(kw) {
        rest.is_empty() || rest.starts_with(char::is_whitespace)
    } else {
        false
    }
}

fn get_indent(line: &str) -> &str {
    let len = line.len() - line.trim_start().len();
    &line[..len]
}

// Convert config to theme YAML
pub fn config_to_theme(config: &str) -> String {
    // Parse bar colors and client lines
    let parsed = parse_colors_from_config(config);

    if parsed.all_hexes.is_empty() {
        return "---\nmeta:\n  description: AUTOMATICALLY GENERATED THEME\ncolors: {}\nwindow_colors: {}\nbar_colors: {}\n".to_string();
    }

    // Map hex values to names
    let mut hex_to_name: HashMap<String, String> = HashMap::new();
    let mut name_count: HashMap<String, usize> = HashMap::new();

    for hex in &parsed.hex_order {
        let base_name = css_colors::find_nearest_color(hex);
        let count = name_count.entry(base_name.to_string()).or_insert(0);
        let name = if *count == 0 {
            base_name.to_string()
        } else {
            format!("{}-{}", base_name, count)
        };
        *count += 1;
        hex_to_name.insert(hex.clone(), name);
    }

    // Build YAML
    let mut yaml = String::new();
    yaml.push_str("---\n");
    yaml.push_str("meta:\n");
    yaml.push_str("  description: AUTOMATICALLY GENERATED THEME\n");
    yaml.push_str("colors:\n");
    for hex in &parsed.hex_order {
        let name = hex_to_name.get(hex).unwrap();
        yaml.push_str(&format!("  {}: \"{}\"\n", name, hex));
    }

    // window_colors
    yaml.push_str("window_colors:\n");

    let wc = &parsed.window_colors;

    if wc.focused.is_some() || wc.focused_inactive.is_some() || 
       wc.unfocused.is_some() || wc.urgent.is_some() {
        macro_rules! emit_wcs {
            ($field:expr, $name:expr) => {
                if let Some(ref c) = $field {
                    yaml.push_str(&format!("  {}:\n", $name));
                    yaml.push_str(&format!("    border: {}\n", hex_to_name.get(&c.0).unwrap_or(&c.0)));
                    yaml.push_str(&format!("    background: {}\n", hex_to_name.get(&c.1).unwrap_or(&c.1)));
                    yaml.push_str(&format!("    text: {}\n", hex_to_name.get(&c.2).unwrap_or(&c.2)));
                    yaml.push_str(&format!("    indicator: {}\n", hex_to_name.get(&c.3).unwrap_or(&c.3)));
                }
            }
        }

        emit_wcs!(wc.focused, "focused");
        emit_wcs!(wc.focused_inactive, "focused_inactive");
        emit_wcs!(wc.unfocused, "unfocused");
        emit_wcs!(wc.urgent, "urgent");
    } else {
        yaml.push_str("  {}\n");  // won't happen but just in case
    }

    // bar_colors
    yaml.push_str("bar_colors:\n");

    let bc = &parsed.bar_colors;

    if bc.background.is_none() && bc.statusline.is_none() && bc.separator.is_none() &&
       bc.focused_workspace.is_none() && bc.urgent_workspace.is_none() {
        yaml.push_str("  {}\n");
    } else {
        if let Some(ref hex) = bc.background {
            yaml.push_str(&format!("  background: {}\n", hex_to_name.get(hex).unwrap_or(hex)));
        }
        if let Some(ref hex) = bc.statusline {
            yaml.push_str(&format!("  statusline: {}\n", hex_to_name.get(hex).unwrap_or(hex)));
        }
        if let Some(ref hex) = bc.separator {
            yaml.push_str(&format!("  separator: {}\n", hex_to_name.get(hex).unwrap_or(hex)));
        }

        macro_rules! emit_bwc {
            ($field:expr, $name:expr) => {
                if let Some(ref c) = $field {
                    yaml.push_str(&format!("  {}:\n", $name));
                    yaml.push_str(&format!("    border: {}\n", hex_to_name.get(&c.0).unwrap_or(&c.0)));
                    yaml.push_str(&format!("    background: {}\n", hex_to_name.get(&c.1).unwrap_or(&c.1)));
                    yaml.push_str(&format!("    text: {}\n", hex_to_name.get(&c.2).unwrap_or(&c.2)));
                }
            }
        }

        emit_bwc!(bc.focused_workspace, "focused_workspace");
        emit_bwc!(bc.urgent_workspace, "urgent_workspace");
    }

    yaml
}

struct ParsedColors {
    hex_order: Vec<String>,
    all_hexes: Vec<String>,
    bar_colors: BarColors,
    window_colors: WindowColors,
}

#[derive(Default)]
struct BarColors {
    background: Option<String>,
    statusline: Option<String>,
    separator: Option<String>,
    focused_workspace: Option<(String, String, String)>,
    urgent_workspace: Option<(String, String, String)>,
}

#[derive(Default)]
struct WindowColors {
    focused: Option<(String, String, String, String)>,
    focused_inactive: Option<(String, String, String, String)>,
    unfocused: Option<(String, String, String, String)>,
    urgent: Option<(String, String, String, String)>,
}

fn parse_colors_from_config(config: &str) -> ParsedColors {
    let mut hex_order: Vec<String> = Vec::new();
    let mut seen_set: std::collections::HashSet<String> = std::collections::HashSet::new();
    let mut bar_colors = BarColors::default();
    let mut window_colors = WindowColors::default();

    let mut in_bar = false;
    let mut in_bar_colors = false;

    let add_hex = |hex: &str, hex_order: &mut Vec<String>, seen_set: &mut std::collections::HashSet<String>| {
        let upper = hex.to_uppercase();
        if !seen_set.contains(&upper) {
            seen_set.insert(upper.clone());
            hex_order.push(upper);
        }
    };

    for line in config.lines() {
        let trimmed = line.trim();

        if is_bar_open(trimmed) {
            in_bar = true;
            in_bar_colors = false;
            continue;
        }

        if in_bar {
            if is_colors_open(trimmed) {
                in_bar_colors = true;
                continue;
            }

            if trimmed == "}" {
                if in_bar_colors {
                    in_bar_colors = false;
                } else {
                    in_bar = false;
                }
                continue;
            }

            if in_bar_colors {
                // Parse bar color lines
                if starts_with_kw(trimmed, "background") {
                    if let Some(hex) = extract_nth_color(trimmed, 1) {
                        add_hex(hex, &mut hex_order, &mut seen_set);
                        bar_colors.background = Some(hex.to_uppercase());
                    }
                } else if starts_with_kw(trimmed, "statusline") {
                    if let Some(hex) = extract_nth_color(trimmed, 1) {
                        add_hex(hex, &mut hex_order, &mut seen_set);
                        bar_colors.statusline = Some(hex.to_uppercase());
                    }
                } else if starts_with_kw(trimmed, "separator") {
                    if let Some(hex) = extract_nth_color(trimmed, 1) {
                        add_hex(hex, &mut hex_order, &mut seen_set);
                        bar_colors.separator = Some(hex.to_uppercase());
                    }
                } else if starts_with_kw(trimmed, "focused_workspace") {
                    let hexes = extract_all_colors(trimmed);
                    for h in &hexes { add_hex(h, &mut hex_order, &mut seen_set); }
                    if hexes.len() >= 3 {
                        bar_colors.focused_workspace = Some((
                            hexes[0].to_uppercase(),
                            hexes[1].to_uppercase(),
                            hexes[2].to_uppercase(),
                        ));
                    }
                } else if starts_with_kw(trimmed, "urgent_workspace") {
                    let hexes = extract_all_colors(trimmed);
                    for h in &hexes { add_hex(h, &mut hex_order, &mut seen_set); }
                    if hexes.len() >= 3 {
                        bar_colors.urgent_workspace = Some((
                            hexes[0].to_uppercase(),
                            hexes[1].to_uppercase(),
                            hexes[2].to_uppercase(),
                        ));
                    }
                } else {
                    // Other workspace types - extract hexes but don't store them specially
                    let hexes = extract_all_colors(trimmed);
                    for h in &hexes { add_hex(h, &mut hex_order, &mut seen_set); }
                }
            }
            continue;
        }

        // Client lines
        macro_rules! parse_client {
            ($kw:expr, $field:expr) => {
                if starts_with_kw(trimmed, $kw) {
                    let hexes = extract_all_colors(trimmed);
                    for h in &hexes { add_hex(h, &mut hex_order, &mut seen_set); }
                    if hexes.len() >= 4 {
                        $field = Some((
                            hexes[0].to_uppercase(),
                            hexes[1].to_uppercase(),
                            hexes[2].to_uppercase(),
                            hexes[3].to_uppercase(),
                        ));
                    }
                }
            }
        }

        if starts_with_kw(trimmed, "client.focused_inactive") {
            let hexes = extract_all_colors(trimmed);
            for h in &hexes { add_hex(h, &mut hex_order, &mut seen_set); }
            if hexes.len() >= 4 {
                window_colors.focused_inactive = Some((
                    hexes[0].to_uppercase(),
                    hexes[1].to_uppercase(),
                    hexes[2].to_uppercase(),
                    hexes[3].to_uppercase(),
                ));
            }
        } else if starts_with_kw(trimmed, "client.focused") {
            let hexes = extract_all_colors(trimmed);
            for h in &hexes { add_hex(h, &mut hex_order, &mut seen_set); }
            if hexes.len() >= 4 {
                window_colors.focused = Some((
                    hexes[0].to_uppercase(),
                    hexes[1].to_uppercase(),
                    hexes[2].to_uppercase(),
                    hexes[3].to_uppercase(),
                ));
            }
        } else if starts_with_kw(trimmed, "client.unfocused") {
            let hexes = extract_all_colors(trimmed);
            for h in &hexes { add_hex(h, &mut hex_order, &mut seen_set); }
            if hexes.len() >= 4 {
                window_colors.unfocused = Some((
                    hexes[0].to_uppercase(),
                    hexes[1].to_uppercase(),
                    hexes[2].to_uppercase(),
                    hexes[3].to_uppercase(),
                ));
            }
        } else if starts_with_kw(trimmed, "client.urgent") {
            let hexes = extract_all_colors(trimmed);
            for h in &hexes { add_hex(h, &mut hex_order, &mut seen_set); }
            if hexes.len() >= 4 {
                window_colors.urgent = Some((
                    hexes[0].to_uppercase(),
                    hexes[1].to_uppercase(),
                    hexes[2].to_uppercase(),
                    hexes[3].to_uppercase(),
                ));
            }
        }
    }

    ParsedColors {
        hex_order: hex_order.clone(),
        all_hexes: hex_order,
        bar_colors,
        window_colors,
    }
}

