// Returns true if this line opens a bar block in a way we can process
fn is_bar_open(trimmed: &str) -> bool {
    // Match "bar {" where { is not immediately closed on same line
    // Specifically: "bar" followed by optional whitespace then "{" then end of line
    // NOT "bar {}" 
    if !trimmed.starts_with("bar") {
        return false;
    }
    let rest = trimmed[3..].trim_start();
    if rest.starts_with('{') {
        let after = rest[1..].trim();
        // "bar {" with nothing after { -> valid bar open
        // "bar { something }" -> NOT what we handle
        return after.is_empty();
    }
    false
}

fn process_bar_block(lines: &[&str], start: usize, theme: &Theme) -> (Vec<String>, usize) {
    let mut result: Vec<String> = Vec::new();
    let mut i = start;
    let mut depth = 1i32; // we're inside bar {
    let mut colors_block_seen = false;

    // Track what we've seen in the colors block
