                let new_line = replace_bar_color_line(cline, theme,
                    &mut sep_seen, &mut bg_seen, &mut sl_seen,
                    &mut fw_seen, &mut aw_seen, &mut iw_seen, &mut uw_seen);
                result.push(new_line);
                i += 1;
