                ));
            }
        }
    }

    ParsedColors {
        hex_order: hex_order.clone(),
        all_hexes: hex_order,
        bar_colors,
        window_colors,
    }
}

fn extract_nth_color(s: &str, n: usize) -> Option<&str> {
    let mut count = 0;
    let bytes = s.as_bytes();
    let mut pos = 0;

    while pos < bytes.len() {
        if bytes[pos] == b'#' {
            count += 1;
            let start = pos;
            pos += 1;
            while pos < bytes.len() && bytes[pos].is_ascii_hexdigit() {
                pos += 1;
            }
            if count == n {
                return Some(&s[start..pos]);
            }
        } else {
            pos += 1;
        }
    }
    None
}

fn extract_all_colors(s: &str) -> Vec<String> {
    let mut result = Vec::new();
    let bytes = s.as_bytes();
    let mut pos = 0;

    while pos < bytes.len() {
        if bytes[pos] == b'#' {
            let start = pos;
            pos += 1;
            while pos < bytes.len() && bytes[pos].is_ascii_hexdigit() {
                pos += 1;
            }
            if pos - start > 1 {
                result.push(s[start..pos].to_string());
            }
        } else {
            pos += 1;
        }
    }
    result
}
