            // Count depth changes
            for ch in trimmed.chars() {
                match ch {
                    '{' => depth += 1,
                    '}' => depth -= 1,
                    _ => {}
                }
            }
        }

        result.push(line.to_string());
        i += 1;
    }

    (result, i)
