        rest.is_empty() || rest.starts_with(char::is_whitespace)
    } else {
        false
    }
}

fn get_indent(line: &str) -> &str {
    let len = line.len() - line.trim_start().len();
    &line[..len]
}

// Convert config to theme YAML
pub fn config_to_theme(config: &str) -> String {
    // Parse bar colors and client lines
    let parsed = parse_colors_from_config(config);

    if parsed.all_hexes.is_empty() {
        return "---\nmeta:\n  description: AUTOMATICALLY GENERATED THEME\ncolors: {}\nwindow_colors: {}\nbar_colors: {}\n".to_string();
    }

    // Map hex values to names
    let mut hex_to_name: HashMap<String, String> = HashMap::new();
    let mut name_count: HashMap<String, usize> = HashMap::new();

    for hex in &parsed.hex_order {
        let base_name = css_colors::find_nearest_color(hex);
        let count = name_count.entry(base_name.to_string()).or_insert(0);
        let name = if *count == 0 {
            base_name.to_string()
        } else {
            format!("{}-{}", base_name, count)
        };
        *count += 1;
        hex_to_name.insert(hex.clone(), name);
    }

    // Build YAML
    let mut yaml = String::new();
    yaml.push_str("---\n");
    yaml.push_str("meta:\n");
    yaml.push_str("  description: AUTOMATICALLY GENERATED THEME\n");
    yaml.push_str("colors:\n");
    for hex in &parsed.hex_order {
        let name = hex_to_name.get(hex).unwrap();
        yaml.push_str(&format!("  {}: \"{}\"\n", name, hex));
    }

    // window_colors
    yaml.push_str("window_colors:\n");

    let wc = &parsed.window_colors;

    if wc.focused.is_some() || wc.focused_inactive.is_some() || 
       wc.unfocused.is_some() || wc.urgent.is_some() {
        macro_rules! emit_wcs {
            ($field:expr, $name:expr) => {
                if let Some(ref c) = $field {
                    yaml.push_str(&format!("  {}:\n", $name));
                    yaml.push_str(&format!("    border: {}\n", hex_to_name.get(&c.0).unwrap_or(&c.0)));
                    yaml.push_str(&format!("    background: {}\n", hex_to_name.get(&c.1).unwrap_or(&c.1)));
                    yaml.push_str(&format!("    text: {}\n", hex_to_name.get(&c.2).unwrap_or(&c.2)));
                    yaml.push_str(&format!("    indicator: {}\n", hex_to_name.get(&c.3).unwrap_or(&c.3)));
                }
            }
        }

        emit_wcs!(wc.focused, "focused");
        emit_wcs!(wc.focused_inactive, "focused_inactive");
        emit_wcs!(wc.unfocused, "unfocused");
        emit_wcs!(wc.urgent, "urgent");
    } else {
        yaml.push_str("  {}\n");  // won't happen but just in case
    }

    // bar_colors
    yaml.push_str("bar_colors:\n");

    let bc = &parsed.bar_colors;

    if bc.background.is_none() && bc.statusline.is_none() && bc.separator.is_none() &&
       bc.focused_workspace.is_none() && bc.urgent_workspace.is_none() {
        yaml.push_str("  {}\n");
    } else {
        if let Some(ref hex) = bc.background {
            yaml.push_str(&format!("  background: {}\n", hex_to_name.get(hex).unwrap_or(hex)));
        }
        if let Some(ref hex) = bc.statusline {
            yaml.push_str(&format!("  statusline: {}\n", hex_to_name.get(hex).unwrap_or(hex)));
        }
        if let Some(ref hex) = bc.separator {
            yaml.push_str(&format!("  separator: {}\n", hex_to_name.get(hex).unwrap_or(hex)));
        }

        macro_rules! emit_bwc {
            ($field:expr, $name:expr) => {
                if let Some(ref c) = $field {
                    yaml.push_str(&format!("  {}:\n", $name));
                    yaml.push_str(&format!("    border: {}\n", hex_to_name.get(&c.0).unwrap_or(&c.0)));
                    yaml.push_str(&format!("    background: {}\n", hex_to_name.get(&c.1).unwrap_or(&c.1)));
                    yaml.push_str(&format!("    text: {}\n", hex_to_name.get(&c.2).unwrap_or(&c.2)));
                }
            }
        }

        emit_bwc!(bc.focused_workspace, "focused_workspace");
        emit_bwc!(bc.urgent_workspace, "urgent_workspace");
    }

    yaml
}

struct ParsedColors {
    hex_order: Vec<String>,
    all_hexes: Vec<String>,
    bar_colors: BarColors,
    window_colors: WindowColors,
}

#[derive(Default)]
struct BarColors {
    background: Option<String>,
    statusline: Option<String>,
    separator: Option<String>,
    focused_workspace: Option<(String, String, String)>,
    urgent_workspace: Option<(String, String, String)>,
}

#[derive(Default)]
struct WindowColors {
    focused: Option<(String, String, String, String)>,
    focused_inactive: Option<(String, String, String, String)>,
    unfocused: Option<(String, String, String, String)>,
    urgent: Option<(String, String, String, String)>,
}

fn parse_colors_from_config(config: &str) -> ParsedColors {
    let mut hex_order: Vec<String> = Vec::new();
    let mut seen_set: std::collections::HashSet<String> = std::collections::HashSet::new();
    let mut bar_colors = BarColors::default();
    let mut window_colors = WindowColors::default();

    let mut in_bar = false;
    let mut in_bar_colors = false;

    let add_hex = |hex: &str, hex_order: &mut Vec<String>, seen_set: &mut std::collections::HashSet<String>| {
        let upper = hex.to_uppercase();
        if !seen_set.contains(&upper) {
            seen_set.insert(upper.clone());
            hex_order.push(upper);
        }
    };

    for line in config.lines() {
        let trimmed = line.trim();

        if is_bar_open(trimmed) {
            in_bar = true;
            in_bar_colors = false;
            continue;
        }

        if in_bar {
            if is_colors_open(trimmed) {
                in_bar_colors = true;
                continue;
            }

            if trimmed == "}" {
                if in_bar_colors {
                    in_bar_colors = false;
                } else {
                    in_bar = false;
                }
                continue;
            }

            if in_bar_colors {
                // Parse bar color lines
                if starts_with_kw(trimmed, "background") {
                    if let Some(hex) = extract_nth_color(trimmed, 1) {
                        add_hex(hex, &mut hex_order, &mut seen_set);
                        bar_colors.background = Some(hex.to_uppercase());
                    }
                } else if starts_with_kw(trimmed, "statusline") {
                    if let Some(hex) = extract_nth_color(trimmed, 1) {
                        add_hex(hex, &mut hex_order, &mut seen_set);
                        bar_colors.statusline = Some(hex.to_uppercase());
                    }
                } else if starts_with_kw(trimmed, "separator") {
                    if let Some(hex) = extract_nth_color(trimmed, 1) {
                        add_hex(hex, &mut hex_order, &mut seen_set);
                        bar_colors.separator = Some(hex.to_uppercase());
                    }
                } else if starts_with_kw(trimmed, "focused_workspace") {
                    let hexes = extract_all_colors(trimmed);
                    for h in &hexes { add_hex(h, &mut hex_order, &mut seen_set); }
                    if hexes.len() >= 3 {
                        bar_colors.focused_workspace = Some((
                            hexes[0].to_uppercase(),
                            hexes[1].to_uppercase(),
                            hexes[2].to_uppercase(),
                        ));
                    }
                } else if starts_with_kw(trimmed, "urgent_workspace") {
                    let hexes = extract_all_colors(trimmed);
                    for h in &hexes { add_hex(h, &mut hex_order, &mut seen_set); }
                    if hexes.len() >= 3 {
                        bar_colors.urgent_workspace = Some((
                            hexes[0].to_uppercase(),
                            hexes[1].to_uppercase(),
                            hexes[2].to_uppercase(),
                        ));
                    }
                } else {
                    // Other workspace types - extract hexes but don't store them specially
                    let hexes = extract_all_colors(trimmed);
                    for h in &hexes { add_hex(h, &mut hex_order, &mut seen_set); }
                }
            }
            continue;
        }

        // Client lines
        macro_rules! parse_client {
            ($kw:expr, $field:expr) => {
                if starts_with_kw(trimmed, $kw) {
                    let hexes = extract_all_colors(trimmed);
                    for h in &hexes { add_hex(h, &mut hex_order, &mut seen_set); }
                    if hexes.len() >= 4 {
                        $field = Some((
                            hexes[0].to_uppercase(),
                            hexes[1].to_uppercase(),
                            hexes[2].to_uppercase(),
                            hexes[3].to_uppercase(),
                        ));
                    }
                }
            }
        }

        if starts_with_kw(trimmed, "client.focused_inactive") {
            let hexes = extract_all_colors(trimmed);
            for h in &hexes { add_hex(h, &mut hex_order, &mut seen_set); }
            if hexes.len() >= 4 {
                window_colors.focused_inactive = Some((
                    hexes[0].to_uppercase(),
                    hexes[1].to_uppercase(),
                    hexes[2].to_uppercase(),
                    hexes[3].to_uppercase(),
                ));
            }
        } else if starts_with_kw(trimmed, "client.focused") {
            let hexes = extract_all_colors(trimmed);
            for h in &hexes { add_hex(h, &mut hex_order, &mut seen_set); }
            if hexes.len() >= 4 {
                window_colors.focused = Some((
                    hexes[0].to_uppercase(),
                    hexes[1].to_uppercase(),
                    hexes[2].to_uppercase(),
                    hexes[3].to_uppercase(),
                ));
            }
        } else if starts_with_kw(trimmed, "client.unfocused") {
            let hexes = extract_all_colors(trimmed);
            for h in &hexes { add_hex(h, &mut hex_order, &mut seen_set); }
            if hexes.len() >= 4 {
                window_colors.unfocused = Some((
                    hexes[0].to_uppercase(),
                    hexes[1].to_uppercase(),
                    hexes[2].to_uppercase(),
                    hexes[3].to_uppercase(),
                ));
            }
        } else if starts_with_kw(trimmed, "client.urgent") {
            let hexes = extract_all_colors(trimmed);
            for h in &hexes { add_hex(h, &mut hex_order, &mut seen_set); }
            if hexes.len() >= 4 {
                window_colors.urgent = Some((
                    hexes[0].to_uppercase(),
                    hexes[1].to_uppercase(),
                    hexes[2].to_uppercase(),
                    hexes[3].to_uppercase(),
                ));
            }
        }
    }

    ParsedColors {
        hex_order: hex_order.clone(),
        all_hexes: hex_order,
        bar_colors,
        window_colors,
    }
}

fn extract_nth_color(s: &str, n: usize) -> Option<&str> {
    let mut count = 0;
    let bytes = s.as_bytes();
    let mut pos = 0;

    while pos < bytes.len() {
        if bytes[pos] == b'#' {
            count += 1;
            let start = pos;
            pos += 1;
            while pos < bytes.len() && bytes[pos].is_ascii_hexdigit() {
                pos += 1;
            }
            if count == n {
                return Some(&s[start..pos]);
            }
        } else {
            pos += 1;
        }
    }
    None
}

fn extract_all_colors(s: &str) -> Vec<String> {
    let mut result = Vec::new();
    let bytes = s.as_bytes();
    let mut pos = 0;

    while pos < bytes.len() {
        if bytes[pos] == b'#' {
            let start = pos;
            pos += 1;
            while pos < bytes.len() && bytes[pos].is_ascii_hexdigit() {
                pos += 1;
            }
            if pos - start > 1 {
                result.push(s[start..pos].to_string());
            }
        } else {
            pos += 1;
        }
    }
    result
}
