    macro_rules! add_ws {
        ($field:expr, $name:expr) => {
            if let Some(ref bwc) = $field {
                let (b, bg, t) = theme.resolve_bwc(bwc);
                if let (Some(border), Some(bg_val), Some(text)) = (b, bg, t) {
                    lines.push(format!("    {} {} {} {} ", $name, border, bg_val, text));
                }
            }
        }
    }

    add_ws!(theme.bar_focused_workspace, "focused_workspace");
    add_ws!(theme.bar_active_workspace, "active_workspace");
    add_ws!(theme.bar_inactive_workspace, "inactive_workspace");
    add_ws!(theme.bar_urgent_workspace, "urgent_workspace");

    lines.push("  }".to_string());
