                return Some(format!("client.focused_inactive {} {} {} {}", border, bg_val, text, indicator));
            }
        }
        return Some(line.to_string());
    }
    if starts_with_kw(trimmed, "client.focused") {
        *focused_seen = true;
        if let Some(ref wcs) = theme.window_focused {
            let (b, bg, t, ind) = theme.resolve_wcs(wcs);
            if let (Some(border), Some(bg_val), Some(text), Some(indicator)) = (b, bg, t, ind) {
                return Some(format!("client.focused {} {} {} {}", border, bg_val, text, indicator));
            }
        }
        return Some(line.to_string());
    }
    if starts_with_kw(trimmed, "client.unfocused") {
        *unfocused_seen = true;
        if let Some(ref wcs) = theme.window_unfocused {
            let (b, bg, t, ind) = theme.resolve_wcs(wcs);
            if let (Some(border), Some(bg_val), Some(text), Some(indicator)) = (b, bg, t, ind) {
                return Some(format!("client.unfocused {} {} {} {}", border, bg_val, text, indicator));
            }
        }
        return Some(line.to_string());
    }
    if starts_with_kw(trimmed, "client.urgent") {
        *urgent_seen = true;
        if let Some(ref wcs) = theme.window_urgent {
            let (b, bg, t, ind) = theme.resolve_wcs(wcs);
            if let (Some(border), Some(bg_val), Some(text), Some(indicator)) = (b, bg, t, ind) {
                return Some(format!("client.urgent {} {} {} {}", border, bg_val, text, indicator));
            }
        }
        return Some(line.to_string());
    }

    None
}

fn append_missing_clients(result: &mut Vec<String>, theme: &Theme,
    focused: bool, focused_inactive: bool,
    unfocused: bool, urgent: bool) {

    if !focused {
        if let Some(ref wcs) = theme.window_focused {
            let (b, bg, t, ind) = theme.resolve_wcs(wcs);
            if let (Some(border), Some(bg_val), Some(text), Some(indicator)) = (b, bg, t, ind) {
                result.push(format!("client.focused {} {} {} {}", border, bg_val, text, indicator));
            }
        }
    }
    if !focused_inactive {
        if let Some(ref wcs) = theme.window_focused_inactive {
            let (b, bg, t, ind) = theme.resolve_wcs(wcs);
            if let (Some(border), Some(bg_val), Some(text), Some(indicator)) = (b, bg, t, ind) {
                result.push(format!("client.focused_inactive {} {} {} {}", border, bg_val, text, indicator));
            }
        }
    }
    if !unfocused {
        if let Some(ref wcs) = theme.window_unfocused {
            let (b, bg, t, ind) = theme.resolve_wcs(wcs);
            if let (Some(border), Some(bg_val), Some(text), Some(indicator)) = (b, bg, t, ind) {
                result.push(format!("client.unfocused {} {} {} {}", border, bg_val, text, indicator));
            }
        }
    }
    if !urgent {
        if let Some(ref wcs) = theme.window_urgent {
            let (b, bg, t, ind) = theme.resolve_wcs(wcs);
            if let (Some(border), Some(bg_val), Some(text), Some(indicator)) = (b, bg, t, ind) {
                result.push(format!("client.urgent {} {} {} {}", border, bg_val, text, indicator));
            }
        }
    }
}

fn starts_with_kw(s: &str, kw: &str) -> bool {
    if let Some(rest) = s.strip_prefix(kw) {
        rest.is_empty() || rest.starts_with(char::is_whitespace)
    } else {
        false
    }
}

fn get_indent(line: &str) -> &str {
    let len = line.len() - line.trim_start().len();
    &line[..len]
}

// Convert config to theme YAML
pub fn config_to_theme(config: &str) -> String {
    let parsed = parse_colors_from_config(config);

    if parsed.hex_order.is_empty() {
        return "---\nmeta:\n  description: AUTOMATICALLY GENERATED THEME\ncolors: {}\nwindow_colors: {}\nbar_colors: {}\n".to_string();
    }

    let mut hex_to_name: HashMap<String, String> = HashMap::new();
    let mut name_count: HashMap<String, usize> = HashMap::new();

    for hex in &parsed.hex_order {
        let base_name = css_colors::find_nearest_color(hex);
        let count = name_count.entry(base_name.to_string()).or_insert(0);
        let name = if *count == 0 {
            base_name.to_string()
        } else {
            format!("{}-{}", base_name, count)
        };
        *count += 1;
        hex_to_name.insert(hex.clone(), name);
    }

    let mut yaml = String::new();
    yaml.push_str("---\n");
    yaml.push_str("meta:\n");
    yaml.push_str("  description: AUTOMATICALLY GENERATED THEME\n");
    yaml.push_str("colors:\n");
    for hex in &parsed.hex_order {
        let name = hex_to_name.get(hex).unwrap();
        yaml.push_str(&format!("  {}: \"{}\"\n", name, hex));
    }

    yaml.push_str("window_colors:\n");
    let wc = &parsed.window_colors;

    let has_window = wc.focused.is_some() || wc.focused_inactive.is_some() || 
                     wc.unfocused.is_some() || wc.urgent.is_some();

    if !has_window {
        yaml.push_str("  {}\n");
    } else {
        macro_rules! emit_wcs {
            ($field:expr, $name:expr) => {
                if let Some(ref c) = $field {
                    yaml.push_str(&format!("  {}:\n", $name));
                    let b = hex_to_name.get(&c.0).cloned().unwrap_or_else(|| c.0.clone());
                    let bg = hex_to_name.get(&c.1).cloned().unwrap_or_else(|| c.1.clone());
                    let t = hex_to_name.get(&c.2).cloned().unwrap_or_else(|| c.2.clone());
                    let ind = hex_to_name.get(&c.3).cloned().unwrap_or_else(|| c.3.clone());
                    yaml.push_str(&format!("    border: {}\n", b));
                    yaml.push_str(&format!("    background: {}\n", bg));
                    yaml.push_str(&format!("    text: {}\n", t));
                    yaml.push_str(&format!("    indicator: {}\n", ind));
                }
            }
        }
        emit_wcs!(wc.focused, "focused");
        emit_wcs!(wc.focused_inactive, "focused_inactive");
        emit_wcs!(wc.unfocused, "unfocused");
        emit_wcs!(wc.urgent, "urgent");
    }

    yaml.push_str("bar_colors:\n");
    let bc = &parsed.bar_colors;

    let has_bar = bc.background.is_some() || bc.statusline.is_some() || bc.separator.is_some() ||
                  bc.focused_workspace.is_some() || bc.urgent_workspace.is_some();

    if !has_bar {
        yaml.push_str("  {}\n");
    } else {
        if let Some(ref hex) = bc.background {
            let name = hex_to_name.get(hex).cloned().unwrap_or_else(|| hex.clone());
            yaml.push_str(&format!("  background: {}\n", name));
        }
        if let Some(ref hex) = bc.statusline {
            let name = hex_to_name.get(hex).cloned().unwrap_or_else(|| hex.clone());
            yaml.push_str(&format!("  statusline: {}\n", name));
        }
        if let Some(ref hex) = bc.separator {
            let name = hex_to_name.get(hex).cloned().unwrap_or_else(|| hex.clone());
            yaml.push_str(&format!("  separator: {}\n", name));
        }

        macro_rules! emit_bwc {
            ($field:expr, $name:expr) => {
                if let Some(ref c) = $field {
                    yaml.push_str(&format!("  {}:\n", $name));
                    let b = hex_to_name.get(&c.0).cloned().unwrap_or_else(|| c.0.clone());
                    let bg = hex_to_name.get(&c.1).cloned().unwrap_or_else(|| c.1.clone());
                    let t = hex_to_name.get(&c.2).cloned().unwrap_or_else(|| c.2.clone());
                    yaml.push_str(&format!("    border: {}\n", b));
                    yaml.push_str(&format!("    background: {}\n", bg));
                    yaml.push_str(&format!("    text: {}\n", t));
                }
            }
        }
        emit_bwc!(bc.focused_workspace, "focused_workspace");
        emit_bwc!(bc.urgent_workspace, "urgent_workspace");
    }

    yaml
}

struct ParsedColors {
    hex_order: Vec<String>,
    bar_colors: BarColors,
    window_colors: WindowColors,
}

#[derive(Default)]
struct BarColors {
    background: Option<String>,
    statusline: Option<String>,
    separator: Option<String>,
    focused_workspace: Option<(String, String, String)>,
    urgent_workspace: Option<(String, String, String)>,
}

#[derive(Default)]
struct WindowColors {
    focused: Option<(String, String, String, String)>,
    focused_inactive: Option<(String, String, String, String)>,
    unfocused: Option<(String, String, String, String)>,
    urgent: Option<(String, String, String, String)>,
}

fn parse_colors_from_config(config: &str) -> ParsedColors {
    let mut hex_order: Vec<String> = Vec::new();
    let mut seen_set: std::collections::HashSet<String> = std::collections::HashSet::new();
    let mut bar_colors = BarColors::default();
    let mut window_colors = WindowColors::default();

    let mut in_bar = false;
    let mut in_bar_colors = false;

    for line in config.lines() {
        let trimmed = line.trim();

        if is_bar_open(trimmed) {
            in_bar = true;
            in_bar_colors = false;
            continue;
        }

        if in_bar {
            if is_colors_open(trimmed) {
                in_bar_colors = true;
                continue;
            }

            if trimmed == "}" {
                if in_bar_colors {
                    in_bar_colors = false;
                } else {
                    in_bar = false;
                }
                continue;
            }

            if in_bar_colors {
                let hexes = extract_all_colors(trimmed);
                for h in &hexes {
                    let upper = h.to_uppercase();
                    if !seen_set.contains(&upper) {
                        seen_set.insert(upper.clone());
                        hex_order.push(upper);
                    }
                }

                if starts_with_kw(trimmed, "background") && !hexes.is_empty() {
                    bar_colors.background = Some(hexes[0].to_uppercase());
                } else if starts_with_kw(trimmed, "statusline") && !hexes.is_empty() {
                    bar_colors.statusline = Some(hexes[0].to_uppercase());
                } else if starts_with_kw(trimmed, "separator") && !hexes.is_empty() {
                    bar_colors.separator = Some(hexes[0].to_uppercase());
                } else if starts_with_kw(trimmed, "focused_workspace") && hexes.len() >= 3 {
                    bar_colors.focused_workspace = Some((
                        hexes[0].to_uppercase(),
                        hexes[1].to_uppercase(),
                        hexes[2].to_uppercase(),
                    ));
                } else if starts_with_kw(trimmed, "urgent_workspace") && hexes.len() >= 3 {
                    bar_colors.urgent_workspace = Some((
                        hexes[0].to_uppercase(),
                        hexes[1].to_uppercase(),
                        hexes[2].to_uppercase(),
                    ));
                }
            }
            continue;
        }

        // Client lines
        let hexes = extract_all_colors(trimmed);
        for h in &hexes {
            let upper = h.to_uppercase();
            if !seen_set.contains(&upper) {
                seen_set.insert(upper.clone());
                hex_order.push(upper);
            }
        }

        if starts_with_kw(trimmed, "client.focused_inactive") && hexes.len() >= 4 {
            window_colors.focused_inactive = Some((
                hexes[0].to_uppercase(),
                hexes[1].to_uppercase(),
                hexes[2].to_uppercase(),
                hexes[3].to_uppercase(),
            ));
        } else if starts_with_kw(trimmed, "client.focused") && hexes.len() >= 4 {
            window_colors.focused = Some((
                hexes[0].to_uppercase(),
                hexes[1].to_uppercase(),
                hexes[2].to_uppercase(),
                hexes[3].to_uppercase(),
            ));
        } else if starts_with_kw(trimmed, "client.unfocused") && hexes.len() >= 4 {
            window_colors.unfocused = Some((
                hexes[0].to_uppercase(),
                hexes[1].to_uppercase(),
                hexes[2].to_uppercase(),
                hexes[3].to_uppercase(),
            ));
        } else if starts_with_kw(trimmed, "client.urgent") && hexes.len() >= 4 {
            window_colors.urgent = Some((
                hexes[0].to_uppercase(),
                hexes[1].to_uppercase(),
                hexes[2].to_uppercase(),
                hexes[3].to_uppercase(),
            ));
        }
    }

    ParsedColors {
        hex_order,
        bar_colors,
        window_colors,
    }
}
