}

fn is_bar_open(trimmed: &str) -> bool {
    if !trimmed.starts_with("bar") {
        return false;
    }
    let rest = trimmed[3..].trim_start();
    if rest.starts_with('{') {
        let after = rest[1..].trim();
        return after.is_empty();
    }
    false
}

fn is_colors_open(trimmed: &str) -> bool {
    if !trimmed.starts_with("colors") {
        return false;
    }
    let rest = trimmed[6..].trim_start();
    if rest.starts_with('{') {
        let after = rest[1..].trim();
        return after.is_empty();
    }
    false
}

fn process_bar_block(lines: &[&str], start: usize, theme: &Theme) -> (Vec<String>, usize) {
    let mut result: Vec<String> = Vec::new();
    let mut i = start;
    let mut depth = 1i32;
    let mut colors_block_seen = false;

    let mut sep_seen = false;
    let mut bg_seen = false;
    let mut sl_seen = false;
    let mut fw_seen = false;
    let mut aw_seen = false;
    let mut iw_seen = false;
    let mut uw_seen = false;

    while i < lines.len() {
        let line = lines[i];
        let trimmed = line.trim();

        if depth == 1 && !colors_block_seen && is_colors_open(trimmed) {
            colors_block_seen = true;
            result.push(line.to_string());
            i += 1;

            while i < lines.len() {
                let cline = lines[i];
                let ctrimmed = cline.trim();

                if ctrimmed == "}" || ctrimmed == "};" {
                    let additions = get_bar_color_additions(theme,
                        sep_seen, bg_seen, sl_seen,
                        fw_seen, aw_seen, iw_seen, uw_seen);
                    for a in additions {
                        result.push(a);
                    }
                    result.push(cline.to_string());
                    i += 1;
                    break;
                }

                let new_line = replace_bar_color_line(cline, theme,
                    &mut sep_seen, &mut bg_seen, &mut sl_seen,
                    &mut fw_seen, &mut aw_seen, &mut iw_seen, &mut uw_seen);
                result.push(new_line);
                i += 1;
            }
            continue;
        }

        if trimmed == "}" {
            depth -= 1;
            if depth == 0 {
                if !colors_block_seen {
                    let colors_block = generate_colors_block(theme);
                    for l in colors_block {
                        result.push(l);
                    }
                }
                result.push(line.to_string());
                i += 1;
                break;
            }
        } else {
            for ch in trimmed.chars() {
                match ch {
                    '{' => depth += 1,
                    '}' => depth -= 1,
                    _ => {}
                }
            }
        }

        result.push(line.to_string());
        i += 1;
    }

    (result, i)
}

fn replace_bar_color_line(line: &str, theme: &Theme,
    sep_seen: &mut bool, bg_seen: &mut bool, sl_seen: &mut bool,
    fw_seen: &mut bool, aw_seen: &mut bool, iw_seen: &mut bool,
    uw_seen: &mut bool) -> String {

    let trimmed = line.trim();
    let indent = get_indent(line);

    if starts_with_kw(trimmed, "separator") {
        *sep_seen = true;
        if let Some(val) = resolve_opt_color(&theme.bar_separator, theme) {
            return format!("{}separator {}", indent, val);
        }
        return line.to_string();
    }
    if starts_with_kw(trimmed, "background") {
        *bg_seen = true;
        if let Some(val) = resolve_opt_color(&theme.bar_background, theme) {
            return format!("{}background {}", indent, val);
        }
        return line.to_string();
    }
    if starts_with_kw(trimmed, "statusline") {
        *sl_seen = true;
        if let Some(val) = resolve_opt_color(&theme.bar_statusline, theme) {
            return format!("{}statusline {}", indent, val);
        }
        return line.to_string();
    }
    if starts_with_kw(trimmed, "focused_workspace") {
        *fw_seen = true;
        if let Some(ref bwc) = theme.bar_focused_workspace {
            if let Some(new_line) = replace_workspace_line(trimmed, theme, bwc, indent) {
                return new_line;
            }
        }
        return line.to_string();
    }
    if starts_with_kw(trimmed, "active_workspace") {
        *aw_seen = true;
        if let Some(ref bwc) = theme.bar_active_workspace {
            if let Some(new_line) = replace_workspace_line(trimmed, theme, bwc, indent) {
                return new_line;
            }
        }
        return line.to_string();
    }
    if starts_with_kw(trimmed, "inactive_workspace") {
        *iw_seen = true;
        if let Some(ref bwc) = theme.bar_inactive_workspace {
            if let Some(new_line) = replace_workspace_line(trimmed, theme, bwc, indent) {
                return new_line;
            }
        }
        return line.to_string();
    }
    if starts_with_kw(trimmed, "urgent_workspace") {
        *uw_seen = true;
        if let Some(ref bwc) = theme.bar_urgent_workspace {
            if let Some(new_line) = replace_workspace_line(trimmed, theme, bwc, indent) {
                return new_line;
            }
        }
        return line.to_string();
    }

    line.to_string()
}

fn replace_workspace_line(trimmed: &str, theme: &Theme,
    bwc: &crate::theme::BarWorkspaceColors, indent: &str) -> Option<String> {
    let (b, bg, t) = theme.resolve_bwc(bwc);
    let (border, bg_val, text) = (b?, bg?, t?);

    let kw = trimmed.split_whitespace().next()?;
    let orig_3rd = extract_nth_color(trimmed, 3);
    let fourth = orig_3rd.map(|c| format!(" {}", c)).unwrap_or_default();

    Some(format!("{}{} {} {} {}{}", indent, kw, border, bg_val, text, fourth))
}

fn extract_nth_color(s: &str, n: usize) -> Option<&str> {
    let mut count = 0;
    let bytes = s.as_bytes();
    let mut pos = 0;

    while pos < bytes.len() {
        if bytes[pos] == b'#' {
            count += 1;
            let start = pos;
            pos += 1;
            while pos < bytes.len() && bytes[pos].is_ascii_hexdigit() {
                pos += 1;
            }
            if count == n {
                return Some(&s[start..pos]);
            }
        } else {
            pos += 1;
        }
    }
    None
}

fn extract_all_colors(s: &str) -> Vec<String> {
    let mut result = Vec::new();
    let bytes = s.as_bytes();
    let mut pos = 0;

    while pos < bytes.len() {
        if bytes[pos] == b'#' {
            let start = pos;
            pos += 1;
            while pos < bytes.len() && bytes[pos].is_ascii_hexdigit() {
                pos += 1;
            }
            if pos - start > 1 {
                result.push(s[start..pos].to_string());
            }
        } else {
            pos += 1;
        }
    }
    result
}

fn resolve_opt_color<'a>(name: &'a Option<String>, theme: &'a Theme) -> Option<&'a str> {
    name.as_ref().and_then(|n| theme.resolve(n))
}

fn get_bar_color_additions(theme: &Theme,
    sep: bool, bg: bool, sl: bool,
    fw: bool, aw: bool, iw: bool, uw: bool) -> Vec<String> {

    let mut additions = Vec::new();

    if !sep {
        if let Some(val) = resolve_opt_color(&theme.bar_separator, theme) {
            additions.push(format!("    separator {}", val));
        }
    }
    if !bg {
        if let Some(val) = resolve_opt_color(&theme.bar_background, theme) {
            additions.push(format!("    background {}", val));
        }
    }
    if !sl {
        if let Some(val) = resolve_opt_color(&theme.bar_statusline, theme) {
            additions.push(format!("    statusline {}", val));
        }
    }

    macro_rules! add_workspace {
        ($seen:expr, $field:expr, $name:expr) => {
            if !$seen {
                if let Some(ref bwc) = $field {
                    let (b, bg2, t) = theme.resolve_bwc(bwc);
                    if let (Some(border), Some(bg_val), Some(text)) = (b, bg2, t) {
                        additions.push(format!("    {} {} {} {} ", $name, border, bg_val, text));
                    }
                }
            }
        }
    }

    add_workspace!(fw, theme.bar_focused_workspace, "focused_workspace");
    add_workspace!(aw, theme.bar_active_workspace, "active_workspace");
    add_workspace!(iw, theme.bar_inactive_workspace, "inactive_workspace");
    add_workspace!(uw, theme.bar_urgent_workspace, "urgent_workspace");

    additions
}

fn generate_colors_block(theme: &Theme) -> Vec<String> {
    let mut lines = Vec::new();
    lines.push("  colors {".to_string());

    if let Some(ref name) = theme.bar_separator {
        if let Some(val) = theme.resolve(name) {
            lines.push(format!("    separator {}", val));
        }
    }
    if let Some(ref name) = theme.bar_background {
